-- Football manager, stage 1 (D-129, docs/MANAGER.md): clubs, their first 20 players and the cities
-- a club can be from. The game is a section of its own: every table is prefixed mgr_.
-- Backward compatible: only new tables and functions.
--
-- A club and its squad are made in ONE transaction by mgr_create_club, which only the server
-- (service role) may call: the squad is generated by the server, so a user must not be able to
-- hand the database a squad of his own. Players' potential lives in a table nobody can read
-- from the client (no policy, no grant).

create table public.mgr_cities (
  id      smallint generated always as identity primary key,
  country text not null check (country ~ '^[A-Z]{2}$'),
  name    text not null check (char_length(name) between 1 and 60),
  unique (country, name)
);
comment on table public.mgr_cities is 'Cities a club can be from; the list depends on the country of the club.';

insert into public.mgr_cities (country, name) values
  ('BY', 'Минск'), ('BY', 'Гомель'), ('BY', 'Могилёв'), ('BY', 'Витебск'), ('BY', 'Гродно'),
  ('BY', 'Брест'), ('BY', 'Бобруйск'), ('BY', 'Барановичи'), ('BY', 'Борисов'), ('BY', 'Пинск'),
  ('BY', 'Орша'), ('BY', 'Мозырь'), ('BY', 'Солигорск'), ('BY', 'Новополоцк'), ('BY', 'Лида'),
  ('BY', 'Молодечно'), ('BY', 'Полоцк'), ('BY', 'Жлобин'), ('BY', 'Светлогорск'), ('BY', 'Слуцк'),
  ('BY', 'Речица'), ('BY', 'Слоним'), ('BY', 'Кобрин'), ('BY', 'Волковыск'), ('BY', 'Жодино');

create table public.mgr_clubs (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null unique references public.profiles (id) on delete cascade,
  name            text not null
    check (char_length(name) <= 30
      and name ~ '^[A-Za-zА-Яа-яЁёІіЎў0-9]+( [A-Za-zА-Яа-яЁёІіЎў0-9]+)*$'),
  country         text not null default 'BY' check (country in ('BY')),
  city_id         smallint not null references public.mgr_cities (id),
  primary_color   text not null check (primary_color ~ '^#[0-9a-f]{6}$'),
  secondary_color text not null check (secondary_color ~ '^#[0-9a-f]{6}$' and secondary_color <> primary_color),
  -- The squad is made from this value once; kept so it can be checked later.
  squad_seed      text not null,
  created_at      timestamptz not null default now()
);
comment on table public.mgr_clubs is 'A user''s club; one per user. The first squad is generated once from squad_seed.';
create unique index mgr_clubs_name_key on public.mgr_clubs (lower(name));

create table public.mgr_players (
  id              uuid primary key default gen_random_uuid(),
  club_id         uuid not null references public.mgr_clubs (id) on delete cascade,
  first_name      text not null,
  last_name       text not null,
  position        text not null check (position in ('GK', 'DEF', 'MID', 'FWD')),
  citizenship     text not null check (citizenship ~ '^[A-Z]{2}$'),
  -- The club that made the player; never changes when the player moves.
  academy_club_id uuid references public.mgr_clubs (id) on delete set null,
  age             smallint not null check (age between 15 and 45),
  ovr             smallint not null check (ovr between 1 and 99),
  form            smallint not null default 80 check (form between 0 and 100),
  fitness         smallint not null default 80 check (fitness between 0 and 100),
  morale          smallint not null default 80 check (morale between 0 and 100),
  created_at      timestamptz not null default now()
);
comment on column public.mgr_players.ovr is 'Overall rating, the weighted mean of the attributes (src/lib/manager/attributes.ts).';
create index mgr_players_club_idx on public.mgr_players (club_id);

create table public.mgr_player_attributes (
  player_id uuid not null references public.mgr_players (id) on delete cascade,
  attribute text not null,
  value     smallint not null check (value between 1 and 99),
  primary key (player_id, attribute)
);

-- The ceiling of growth: hidden from users on purpose, so it has no policy and no grant.
create table public.mgr_player_hidden (
  player_id uuid primary key references public.mgr_players (id) on delete cascade,
  potential smallint not null check (potential between 1 and 99)
);

alter table public.mgr_cities enable row level security;
alter table public.mgr_clubs enable row level security;
alter table public.mgr_players enable row level security;
alter table public.mgr_player_attributes enable row level security;
alter table public.mgr_player_hidden enable row level security;

-- Signed-in users read the cities and their own club with its squad (stage 2 widens this to the league).
create policy mgr_cities_select on public.mgr_cities for select to authenticated using (true);

create policy mgr_clubs_select on public.mgr_clubs for select to authenticated
  using (user_id = (select auth.uid()));

create policy mgr_players_select on public.mgr_players for select to authenticated
  using (exists (
    select 1 from public.mgr_clubs c
    where c.id = club_id and c.user_id = (select auth.uid())
  ));

create policy mgr_player_attributes_select on public.mgr_player_attributes for select to authenticated
  using (exists (
    select 1 from public.mgr_players p
    join public.mgr_clubs c on c.id = p.club_id
    where p.id = player_id and c.user_id = (select auth.uid())
  ));

revoke all on public.mgr_cities, public.mgr_clubs, public.mgr_players,
  public.mgr_player_attributes, public.mgr_player_hidden from anon, authenticated;
grant select on public.mgr_cities, public.mgr_clubs, public.mgr_players,
  public.mgr_player_attributes to authenticated;

-- Makes the club and its squad together. Called by the server only (the squad comes from the
-- generator): refuses a second club, a taken name and any squad that is not the same for everyone.
create or replace function public.mgr_create_club(
  p_user    uuid,
  p_name    text,
  p_city    smallint,
  p_primary text,
  p_secondary text,
  p_seed    text,
  p_players jsonb
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_club    uuid;
  v_player  uuid;
  v_item    jsonb;
  v_attr    record;
  v_total   integer;
  v_country text;
begin
  if exists (select 1 from public.mgr_clubs where user_id = p_user) then
    raise exception 'manager.club_exists' using errcode = 'P0001';
  end if;
  select country into v_country from public.mgr_cities where id = p_city;
  if v_country is null then
    raise exception 'manager.city_unknown' using errcode = 'P0001';
  end if;

  -- The rules of a starting squad (the same for every club).
  if jsonb_typeof(p_players) <> 'array' or jsonb_array_length(p_players) <> 20 then
    raise exception 'manager.squad_invalid' using errcode = 'P0001';
  end if;
  select sum((x ->> 'ovr')::int) into v_total from jsonb_array_elements(p_players) x;
  if v_total is distinct from 1200 then
    raise exception 'manager.squad_invalid' using errcode = 'P0001';
  end if;
  if (select count(*) from jsonb_array_elements(p_players) x where x ->> 'position' = 'GK') <> 2
     or (select count(*) from jsonb_array_elements(p_players) x where x ->> 'position' = 'DEF') <> 7
     or (select count(*) from jsonb_array_elements(p_players) x where x ->> 'position' = 'MID') <> 7
     or (select count(*) from jsonb_array_elements(p_players) x where x ->> 'position' = 'FWD') <> 4 then
    raise exception 'manager.squad_invalid' using errcode = 'P0001';
  end if;

  begin
    insert into public.mgr_clubs (user_id, name, country, city_id, primary_color, secondary_color, squad_seed)
    values (p_user, p_name, v_country, p_city, p_primary, p_secondary, p_seed)
    returning id into v_club;
  exception when unique_violation then
    raise exception 'manager.name_taken' using errcode = 'P0001';
  end;

  for v_item in select * from jsonb_array_elements(p_players) loop
    insert into public.mgr_players (club_id, first_name, last_name, position, citizenship, academy_club_id, age, ovr)
    values (
      v_club, v_item ->> 'first_name', v_item ->> 'last_name', v_item ->> 'position',
      v_country, v_club, (v_item ->> 'age')::smallint, (v_item ->> 'ovr')::smallint
    )
    returning id into v_player;

    for v_attr in select key, value from jsonb_each_text(v_item -> 'attributes') loop
      insert into public.mgr_player_attributes (player_id, attribute, value)
      values (v_player, v_attr.key, v_attr.value::smallint);
    end loop;

    insert into public.mgr_player_hidden (player_id, potential)
    values (v_player, (v_item ->> 'potential')::smallint);
  end loop;

  return v_club;
end;
$$;

revoke execute on function public.mgr_create_club(uuid, text, smallint, text, text, text, jsonb)
  from public, anon, authenticated;
grant execute on function public.mgr_create_club(uuid, text, smallint, text, text, text, jsonb)
  to service_role;
